import mongoose from "mongoose";

const MessageSchema = new mongoose.Schema({
    role: {
        type: String,
        enum: ["user", "assistant"],
        required: true
    },
    content: {
        type: String,
        required: true
    },
    timestamp: {
        type: Date,
        default: Date.now
    }
});

const ThreadSchema = new mongoose.Schema({
    // Authenticated owner — null for guest threads
    userId: {
        type: mongoose.Schema.Types.ObjectId,
        ref: "User"
    },
    // Anonymous owner — random UUID generated by the browser and stored in localStorage.
    // sparse=true so the unique index only enforces uniqueness among non-null values.
    guestId: {
        type: String
    },
    threadId: {
        type: String,
        required: true,
        unique: true
    },
    title: {
        type: String,
        default: "New Chat"
    },
    messages: [MessageSchema]
}, { timestamps: true });

// Serve the sidebar query: "this owner's threads, newest first, paginated".
ThreadSchema.index({ userId: 1, updatedAt: -1, _id: -1 });
ThreadSchema.index({ guestId: 1, updatedAt: -1, _id: -1 });

export default mongoose.model("Thread", ThreadSchema);